     * iteration only reads x[] and y[], so a simple parallel-for over i is
     * fully race-free.  Because work per i is highly irregular (dense
     * clusters), we use a dynamic schedule so threads that finish fast
     * iterations pick up new chunks, and to keep P-cores busy while E-cores
     * lag behind.  A modest chunk size amortizes scheduling overhead. */
    #pragma omp parallel for schedule(dynamic, 64)
    for (long i = 0; i < n; i++) {
        int c = 0;
        for (long j = i + 1; j < n && x[j] - x[i] <= r; j++) {
            double dx = x[j] - x[i], dy = y[j] - y[i];
